exercises.starter_code:
#include <stdio.h>

int main(void) {
    // struct Rectangle + area fn
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    struct Rectangle { double w, h; };
    double rect_area(struct Rectangle r) { return r.w * r.h; }
    struct Rectangle rect = {3, 4};
    printf("%g\n", rect_area(rect));
    return 0;
}

