exercises.solution:
#include <stdio.h>

typedef int (*writer_fn)(const char *);
static int logger_write(const char *msg) {
    (void)msg;
    return 5;
}

int main(void) {
writer_fn w = logger_write;
printf("%d %s", w("hello"), "hello");
    return 0;
}

exercises.starter_code:
#include <stdio.h>
#include <math.h>

int main(void) {
    // compare circle vs rect area
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <math.h>

int main(void) {
    double pi = 3.14159265358979323846;
    double circle = pi * 5 * 5;
    double rect = 12;
    printf("%.14g\n", circle > rect ? circle : rect);
    return 0;
}

